import axios, { AxiosError, type AxiosResponse } from 'axios'
import { useSnackbar } from 'notistack'
import { useAuthHeader } from 'react-auth-kit'
import type { UseMutationResult } from 'react-query'
import { useMutation, useQuery, useQueryClient } from 'react-query'
import { useNavigate } from 'react-router'

import { COMMON_MESSAGE } from 'src/data/messages'

import type {
  CreateActivityPostReqDto,
  CreateImageResDto,
  GetActivityPostResDto,
  GetRecentActivitiesResponse,
  UpdateActivityPostReqDto
} from 'src/models/activity'
import type { ClubId } from 'src/models/club'

const getPublicActivitiesAPICall = async (clubId: number) => {
  const response = await axios.get<GetRecentActivitiesResponse>(
    `${process.env.REACT_APP_APIHOST}/club/${clubId}/activity`
  )
  return response.data
}

export const useGetPublicActivities = (clubId: number) => {
  const { enqueueSnackbar } = useSnackbar()

  const publicActivities = useQuery(['publicActivities', clubId], () => getPublicActivitiesAPICall(clubId), {
    onError: err => {
      if (err instanceof AxiosError) {
        enqueueSnackbar(COMMON_MESSAGE.LOAD_FAIL, { variant: 'error' })
        return
      }
      enqueueSnackbar(COMMON_MESSAGE.UNKNOWN_ERROR, { variant: 'error' })
    }
  })
  return publicActivities
}

const getRecentActivitiesAPICall = async (limit: number) => {
  const response = await axios.get<GetRecentActivitiesResponse>(
    `${process.env.REACT_APP_APIHOST}/home/activities/recent`,
    {
      params: { limit }
    }
  )
  return response.data
}

export const useGetRecentActivities = (limit: number = 12) => {
  const { enqueueSnackbar } = useSnackbar()

  const recentActivities = useQuery(['recentActivities', limit], () => getRecentActivitiesAPICall(limit), {
    onError: err => {
      if (err instanceof AxiosError) {
        enqueueSnackbar(COMMON_MESSAGE.LOAD_FAIL, { variant: 'error' })
        return
      }
      enqueueSnackbar(COMMON_MESSAGE.UNKNOWN_ERROR, { variant: 'error' })
    }
  })
  return recentActivities
}

// 관리자용 활동 목록 조회 (비공개 포함)
const getAdminActivitiesAPICall = async (clubId: ClubId, token: string) => {
  const response = await axios.get<GetRecentActivitiesResponse>(
    `${process.env.REACT_APP_APIHOST}/club/${clubId}/activity/admin`,
    {
      headers: { Authorization: token }
    }
  )
  return response.data
}

export const useGetAdminActivities = (clubId: ClubId) => {
  const { enqueueSnackbar } = useSnackbar()
  const token = useAuthHeader()()

  return useQuery(['adminActivities', clubId], () => getAdminActivitiesAPICall(clubId, token), {
    onError: err => {
      if (err instanceof AxiosError) {
        enqueueSnackbar(COMMON_MESSAGE.LOAD_FAIL, { variant: 'error' })
        return
      }
      enqueueSnackbar(COMMON_MESSAGE.UNKNOWN_ERROR, { variant: 'error' })
    }
  })
}

// 활동 게시물 단건 조회
const getActivityPostAPICall = async (clubId: ClubId, postId: number, token?: string) => {
  const response = await axios.get<GetActivityPostResDto>(
    `${process.env.REACT_APP_APIHOST}/club/${clubId}/activity/${postId}`,
    token ? { headers: { Authorization: token } } : {}
  )
  return response.data
}

export const useGetActivityPost = (clubId: ClubId, postId: number) => {
  const { enqueueSnackbar } = useSnackbar()
  const token = useAuthHeader()()

  return useQuery(['activityPost', clubId, postId], () => getActivityPostAPICall(clubId, postId, token), {
    enabled: postId > 0,
    onError: err => {
      if (err instanceof AxiosError) {
        enqueueSnackbar(COMMON_MESSAGE.LOAD_FAIL, { variant: 'error' })
        return
      }
      enqueueSnackbar(COMMON_MESSAGE.UNKNOWN_ERROR, { variant: 'error' })
    }
  })
}

// 활동 게시물 생성
const postActivityPostAPICall = async (clubId: ClubId, data: CreateActivityPostReqDto, token: string) => {
  await axios.post<null, AxiosResponse<null>, CreateActivityPostReqDto>(
    `${process.env.REACT_APP_APIHOST}/club/${clubId}/activity`,
    data,
    {
      headers: { Authorization: token }
    }
  )
}

export const useCreateActivityPost = (
  clubId: ClubId
): UseMutationResult<void, unknown, CreateActivityPostReqDto, unknown> => {
  const { enqueueSnackbar } = useSnackbar()
  const token = useAuthHeader()()
  const queryClient = useQueryClient()
  const navigate = useNavigate()

  const mutationFn = (values: CreateActivityPostReqDto) => postActivityPostAPICall(clubId, values, token)

  return useMutation(mutationFn, {
    onSuccess: () => {
      enqueueSnackbar(COMMON_MESSAGE.ADD_SUCCESS, { variant: 'success' })
      queryClient.invalidateQueries(['adminActivities', clubId])
      navigate(`/manage/${clubId}/activity`)
    },
    onError: error => {
      if (error instanceof AxiosError) {
        const errorMessage = error?.response?.data?.message ?? COMMON_MESSAGE.ADD_FAIL
        enqueueSnackbar(errorMessage, { variant: 'error' })
      } else {
        enqueueSnackbar(COMMON_MESSAGE.UNKNOWN_ERROR, { variant: 'error' })
      }
    }
  })
}

// 활동 게시물 수정
const patchActivityPostAPICall = async (
  clubId: ClubId,
  postId: number,
  data: UpdateActivityPostReqDto,
  token: string
) => {
  await axios.patch<null, AxiosResponse<null>, UpdateActivityPostReqDto>(
    `${process.env.REACT_APP_APIHOST}/club/${clubId}/activity/${postId}`,
    data,
    {
      headers: { Authorization: token }
    }
  )
}

export const usePatchActivityPost = (
  clubId: ClubId,
  postId: number
): UseMutationResult<void, unknown, UpdateActivityPostReqDto, unknown> => {
  const { enqueueSnackbar } = useSnackbar()
  const token = useAuthHeader()()
  const queryClient = useQueryClient()
  const navigate = useNavigate()

  const mutationFn = (values: UpdateActivityPostReqDto) => patchActivityPostAPICall(clubId, postId, values, token)

  return useMutation(mutationFn, {
    onSuccess: () => {
      enqueueSnackbar(COMMON_MESSAGE.UPDATE_SUCCESS, { variant: 'success' })
      queryClient.invalidateQueries(['adminActivities', clubId])
      queryClient.invalidateQueries(['activityPost', clubId, postId])
      navigate(`/manage/${clubId}/activity`)
    },
    onError: error => {
      if (error instanceof AxiosError) {
        const errorMessage = error?.response?.data?.message ?? COMMON_MESSAGE.UPDATE_FAIL
        enqueueSnackbar(errorMessage, { variant: 'error' })
      } else {
        enqueueSnackbar(COMMON_MESSAGE.UNKNOWN_ERROR, { variant: 'error' })
      }
    }
  })
}

// 활동 게시물 삭제
const deleteActivityPostAPICall = async (clubId: ClubId, postId: number, token: string) => {
  await axios.delete<null, AxiosResponse<null>, null>(
    `${process.env.REACT_APP_APIHOST}/club/${clubId}/activity/${postId}`,
    {
      headers: { Authorization: token }
    }
  )
}

export const useDeleteActivityPost = (clubId: ClubId, postIds: number[], successMessage: string) => {
  const { enqueueSnackbar } = useSnackbar()
  const token = useAuthHeader()()
  const queryClient = useQueryClient()

  const mutationFn = async () => {
    await Promise.all(postIds.map(postId => deleteActivityPostAPICall(clubId, postId, token)))
  }

  return useMutation(mutationFn, {
    onSuccess: () => {
      enqueueSnackbar(successMessage, { variant: 'success' })
      queryClient.invalidateQueries(['adminActivities', clubId])
    },
    onError: err => {
      if (err instanceof AxiosError) {
        enqueueSnackbar(err.response?.data?.message ?? COMMON_MESSAGE.SERVER_ERROR, { variant: 'error' })
        return
      }
      enqueueSnackbar(COMMON_MESSAGE.UNKNOWN_ERROR, { variant: 'error' })
    }
  })
}

// 활동 게시물 이미지 업로드
const uploadActivityImageAPICall = async (clubId: ClubId, file: File, token: string) => {
  const formData = new FormData()
  formData.append('img', file)

  const response = await axios.post<CreateImageResDto>(
    `${process.env.REACT_APP_APIHOST}/club/${clubId}/activity/img`,
    formData,
    {
      headers: { Authorization: token }
    }
  )
  return response.data
}

export const useUploadActivityImage = (clubId: ClubId) => {
  const { enqueueSnackbar } = useSnackbar()
  const token = useAuthHeader()()

  const mutationFn = (file: File) => uploadActivityImageAPICall(clubId, file, token)

  return useMutation(mutationFn, {
    onError: error => {
      if (error instanceof AxiosError) {
        const errorMessage = error?.response?.data?.message ?? '이미지 업로드에 실패했어요.'
        enqueueSnackbar(errorMessage, { variant: 'error' })
      } else {
        enqueueSnackbar(COMMON_MESSAGE.UNKNOWN_ERROR, { variant: 'error' })
      }
    }
  })
}
