import { Link } from 'react-router-dom'

import { Link as LinkIcon } from '@mui/icons-material'
import { Avatar, Box, Grid, Tooltip, Typography } from '@mui/material'

import { type Club } from 'src/models/club'

import ClubChip from 'src/components/ClubChip'
import InstagramConnect from 'src/components/InstagramConnect'
import LikeBtn from 'src/components/LikeBtn'

interface ClubInfoProps {
  club: Club
  handleLike: (event: React.MouseEvent<HTMLButtonElement>) => void
  isLike: boolean
  isDesktopOrTablet: boolean
  isDummy?: boolean
}

export const ClubInfo: React.FC<ClubInfoProps> = ({ club, handleLike, isLike, isDesktopOrTablet, isDummy }) => {
  return (
    <Grid item xs={12} md={7}>
      <Box display="flex" flexDirection="row" gap={2} mt={2}>
        {club.profileImageUrl && (
          <Avatar
            src={club.profileImageUrl}
            alt={club.name}
            sx={{
              width: 100,
              height: 100,
              border: '1px solid',
              borderColor: 'divider',
              flexShrink: 0
            }}
          />
        )}
        <Box flex={1}>
          <Box
            display="flex"
            flexDirection={isDesktopOrTablet ? 'row' : 'column'}
            alignItems={isDesktopOrTablet ? 'center' : ''}
            mb={1}
          >
            <Box display="flex" flexDirection="row" alignItems="center" marginRight="10px">
              <Link to={`/club/${club.id}`} style={{ textDecoration: 'none' }}>
                <Typography variant="h3" mr={1}>
                  {club.name}
                </Typography>
              </Link>
              {club?.instagramId && <InstagramConnect instagramId={club.instagramId} />}
              <LikeBtn handleLike={handleLike} isLike={isLike} />
              {isDummy && (
                <Tooltip title={'이 동아리는 현재 운영진으로 등록된 회원이 없어요!'} placement="top-end">
                  <Link to="/club/register" target="_blank" style={{ textDecoration: 'none' }}>
                    <Box display={'flex'} alignContent={'center'} gap={1} ml={2}>
                      <Typography variant="body1" fontWeight={'bold'} color="primary">
                        "{club.name}"의 대표자로 등록하기
                      </Typography>
                      <LinkIcon fontSize="small" color="primary" />
                    </Box>
                  </Link>
                </Tooltip>
              )}
            </Box>
          </Box>
          <Typography variant="subtitle2" mb={1}>
            {club.description}
          </Typography>
          <Box>
            {club.belonging && <ClubChip label={club.belonging} isDesktopOrTablet={isDesktopOrTablet} />}
            {club.categoryMain && <ClubChip label={club.categoryMain} isDesktopOrTablet={isDesktopOrTablet} />}
            {club.categorySub && <ClubChip label={club.categorySub} isDesktopOrTablet={isDesktopOrTablet} />}
            {club.location && <ClubChip label={club.location} isDesktopOrTablet={isDesktopOrTablet} />}
          </Box>
        </Box>
      </Box>
    </Grid>
  )
}
