import { useEffect, useState } from 'react'
import { Helmet } from 'react-helmet-async'
import { useParams } from 'react-router'
import { useSetRecoilState } from 'recoil'

import { Box, Card, Chip, Container, Grid, Stack, Typography, useMediaQuery, useTheme } from '@mui/material'
import 'src/components/TextEditor/TextEditor.css'

import { formatDate } from 'src/utils/formatDateTime'

import { ClubInfo } from 'src/components/ClubInfo'
import PageTitleWrapper from 'src/components/PageTitleWrapper'
import SuspenseLoader from 'src/components/SuspenseLoader'

import { useGetActivityPost } from 'src/hooks/api/activityHooks'
import { useDeleteLikeClub, useGetClubInformation, usePostLikeClub } from 'src/hooks/api/club'
import { useGetConferenceRound } from 'src/hooks/api/clubConferenceHooks'
import { isLikeBtnClickedAtom } from 'src/recoil/atom'

const ActivityPage: React.FC = () => {
  const { id, roundId, postId } = useParams()
  const clubId = Number(id)
  const roundIdNum = roundId ? Number(roundId) : null
  const activityPostId = postId ? Number(postId) : null

  const theme = useTheme()
  const isUpMd = useMediaQuery(theme.breakpoints.up('md')) // >= 960px
  const isUpSm = useMediaQuery(theme.breakpoints.up('sm')) // >= 600px

  const [isLike, setIsLike] = useState(false)
  const setIsLikeBtnClicked = useSetRecoilState(isLikeBtnClickedAtom)

  // URL 패턴에 따라 분기: /club/{id}/conference/round/{roundId} vs /club/{id}/post/{postId}
  const isActivityPost = postId !== undefined

  const { data: club, isFetched: isClubFetched } = useGetClubInformation(clubId)

  // 조건부로 API 호출
  const { data: conferenceRound, isLoading: isConferenceLoading } = useGetConferenceRound(clubId, roundIdNum ?? 0, {
    enabled: !isActivityPost && roundIdNum !== null
  })
  const { data: activityPost, isLoading: isActivityLoading } = useGetActivityPost(clubId, activityPostId ?? 0)

  const postLikeClubMutation = usePostLikeClub(clubId)
  const deleteLikeClubMutation = useDeleteLikeClub(clubId)

  useEffect(() => {
    if (isClubFetched && club) {
      setIsLike(club.isliked)
    }
  }, [isClubFetched, club])

  const handleLike: React.MouseEventHandler<HTMLButtonElement> = async () => {
    try {
      if (isLike) {
        await deleteLikeClubMutation.mutateAsync()
      } else {
        await postLikeClubMutation.mutateAsync()
      }
      setIsLike(!isLike)
      setIsLikeBtnClicked(true)
    } catch (error) {}
  }

  const isLoading = isActivityPost ? isActivityLoading : isConferenceLoading
  const content = isActivityPost ? activityPost : conferenceRound
  const startDate = isActivityPost ? activityPost?.activityDate : conferenceRound?.startAt
  const startDateLabel = startDate ? formatDate(new Date(startDate)) : ''
  const title = isActivityPost ? activityPost?.title : conferenceRound?.conferenceTitle

  return (
    <>
      <Helmet>
        <title>{title ?? 'Activity'}</title>
      </Helmet>

      <PageTitleWrapper>
        <Grid container>
          {club && <ClubInfo club={club} handleLike={handleLike} isLike={isLike} isDesktopOrTablet={isUpSm} />}
        </Grid>
      </PageTitleWrapper>

      <Container maxWidth="md">
        {isLoading ? (
          <SuspenseLoader />
        ) : content ? (
          <Card sx={{ px: isUpMd ? 10 : isUpSm ? 5 : 2, py: isUpSm ? 5 : 2 }}>
            <Stack spacing={2}>
              <Typography sx={{ fontSize: '20px', fontWeight: 'bold' }} overflow="auto">
                {title}
              </Typography>

              <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                <Typography variant="body2" color="text.secondary">
                  {startDateLabel}
                </Typography>
                <Box sx={{ display: 'flex', gap: 0.75 }}>
                  {content.categories?.map((category: string, index: number) => (
                    <Chip key={index} label={category} size="small" variant="filled" />
                  ))}
                </Box>
              </Box>

              <Box sx={{ mt: 1 }}>
                <div className="tiptap-content-display" dangerouslySetInnerHTML={{ __html: content.note }}></div>
              </Box>
            </Stack>
          </Card>
        ) : (
          <Card>
            <Box height="40vh" display="flex" justifyContent="center" alignItems="center">
              <Typography variant="h6">활동 기록을 찾을 수 없어요.</Typography>
            </Box>
          </Card>
        )}
      </Container>
    </>
  )
}

export default ActivityPage
